#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <immintrin.h>

/* OpenSSL */
int ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                   const unsigned int key[8], const unsigned int counter[4]);

static inline uint32_t rotl(uint32_t x, int n) { return (x << n) | (x >> (32-n)); }

static inline void qr(uint32_t *a, uint32_t *b, uint32_t *c, uint32_t *d) {
    *a += *b; *d ^= *a; *d = rotl(*d, 16);
    *c += *d; *b ^= *c; *b = rotl(*b, 12);
    *a += *b; *d ^= *a; *d = rotl(*d, 8);
    *c += *d; *b ^= *c; *b = rotl(*b, 7);
}

/* 4-way AVX2 ChaCha20 */
static inline __m256i rotl_avx(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32-n));
}
static inline void qr_avx(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl_avx(*d, 16);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl_avx(*b, 12);
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl_avx(*d, 8);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl_avx(*b, 7);
}

/* Column-round then diagonal. State laid out as 4 blocks in AoS-of-vectors:
   x0 holds state[0] of blocks 0..3, etc. */
static void chacha20_4blocks(uint32_t out[64], const uint32_t state[16]) {
    __m256i x[16];
    for (int i = 0; i < 16; i++) {
        x[i] = _mm256_set1_epi32(state[i]);
    }
    /* add block counters 0,1,2,3 to word 12 */
    __m256i inc = _mm256_set_epi32(3,2,1,0, 3,2,1,0); /* wait 256 is 8 lanes. We want 4x u32. */
    /* redo: __m256i is 8 x u32. We only want 4 blocks = 4 lanes. Use lower? 
       Actually let's do 8 blocks for better ILP. */
}

/* 4 blocks using __m128? Let's do 4-wide with 128-bit for simplicity first, then 8. */
static void chacha_xor4(unsigned char *out, const unsigned char *in, size_t blocks,
                        const uint32_t key[8], const uint32_t counter[4]) {
    /* process 4 blocks at a time using AVX2 8-wide would be better; start with 4 via set */
    uint32_t ctr = counter[0];
    uint32_t c1 = counter[1], c2 = counter[2], c3 = counter[3];
    const uint32_t k0=key[0],k1=key[1],k2=key[2],k3=key[3],k4=key[4],k5=key[5],k6=key[6],k7=key[7];
    /* constants */
    const uint32_t s0=0x61707865, s1=0x3320646e, s2=0x79622d32, s3=0x6b206574;

    size_t done = 0;
    while (done + 4 <= blocks) {
        __m256i v0 = _mm256_set1_epi32(s0);
        __m256i v1 = _mm256_set1_epi32(s1);
        __m256i v2 = _mm256_set1_epi32(s2);
        __m256i v3 = _mm256_set1_epi32(s3);
        __m256i v4 = _mm256_set1_epi32(k0);
        __m256i v5 = _mm256_set1_epi32(k1);
        __m256i v6 = _mm256_set1_epi32(k2);
        __m256i v7 = _mm256_set1_epi32(k3);
        __m256i v8 = _mm256_set1_epi32(k4);
        __m256i v9 = _mm256_set1_epi32(k5);
        __m256i v10= _mm256_set1_epi32(k6);
        __m256i v11= _mm256_set1_epi32(k7);
        /* 8 counters in low? set_epi32 is high to low: lane7 .. lane0. We use 4 lanes of a 256? 
           Let's pack 8 blocks. */
        (void)v0;(void)ctr;(void)c1;
        break;
    }
}

/* Proper 8-block AVX2 */
static void chacha20_xor(unsigned char *out, const unsigned char *in, size_t len,
                         const unsigned char key[32], const unsigned char nonce[12], uint32_t counter) {
    uint32_t k[8];
    memcpy(k, key, 32);
    uint32_t n0, n1, n2;
    memcpy(&n0, nonce, 4);
    memcpy(&n1, nonce+4, 4);
    memcpy(&n2, nonce+8, 4);

    const uint32_t s0=0x61707865u, s1=0x3320646eu, s2=0x79622d32u, s3=0x6b206574u;

    size_t off = 0;
    while (off + 512 <= len) {
        __m256i v0  = _mm256_set1_epi32(s0);
        __m256i v1  = _mm256_set1_epi32(s1);
        __m256i v2  = _mm256_set1_epi32(s2);
        __m256i v3  = _mm256_set1_epi32(s3);
        __m256i v4  = _mm256_set1_epi32(k[0]);
        __m256i v5  = _mm256_set1_epi32(k[1]);
        __m256i v6  = _mm256_set1_epi32(k[2]);
        __m256i v7  = _mm256_set1_epi32(k[3]);
        __m256i v8  = _mm256_set1_epi32(k[4]);
        __m256i v9  = _mm256_set1_epi32(k[5]);
        __m256i v10 = _mm256_set1_epi32(k[6]);
        __m256i v11 = _mm256_set1_epi32(k[7]);
        __m256i v12 = _mm256_set_epi32(counter+7, counter+6, counter+5, counter+4,
                                       counter+3, counter+2, counter+1, counter+0);
        __m256i v13 = _mm256_set1_epi32(n0);
        __m256i v14 = _mm256_set1_epi32(n1);
        __m256i v15 = _mm256_set1_epi32(n2);

        __m256i x0=v0,x1=v1,x2=v2,x3=v3,x4=v4,x5=v5,x6=v6,x7=v7;
        __m256i x8=v8,x9=v9,x10=v10,x11=v11,x12=v12,x13=v13,x14=v14,x15=v15;

        for (int r = 0; r < 10; r++) {
            /* column */
            qr_avx(&x0,&x4,&x8,&x12);
            qr_avx(&x1,&x5,&x9,&x13);
            qr_avx(&x2,&x6,&x10,&x14);
            qr_avx(&x3,&x7,&x11,&x15);
            /* diagonal */
            qr_avx(&x0,&x5,&x10,&x15);
            qr_avx(&x1,&x6,&x11,&x12);
            qr_avx(&x2,&x7,&x8,&x13);
            qr_avx(&x3,&x4,&x9,&x14);
        }
        x0=_mm256_add_epi32(x0,v0); x1=_mm256_add_epi32(x1,v1);
        x2=_mm256_add_epi32(x2,v2); x3=_mm256_add_epi32(x3,v3);
        x4=_mm256_add_epi32(x4,v4); x5=_mm256_add_epi32(x5,v5);
        x6=_mm256_add_epi32(x6,v6); x7=_mm256_add_epi32(x7,v7);
        x8=_mm256_add_epi32(x8,v8); x9=_mm256_add_epi32(x9,v9);
        x10=_mm256_add_epi32(x10,v10); x11=_mm256_add_epi32(x11,v11);
        x12=_mm256_add_epi32(x12,v12); x13=_mm256_add_epi32(x13,v13);
        x14=_mm256_add_epi32(x14,v14); x15=_mm256_add_epi32(x15,v15);

        /* transpose 8x16 matrix of u32 into 8 sequential 64-byte blocks.
           Each block i consists of words x0[i], x1[i], ... x15[i].
           Store via extract. */
        uint32_t tmp[16][8];
        _mm256_storeu_si256((__m256i*)tmp[0], x0);
        _mm256_storeu_si256((__m256i*)tmp[1], x1);
        _mm256_storeu_si256((__m256i*)tmp[2], x2);
        _mm256_storeu_si256((__m256i*)tmp[3], x3);
        _mm256_storeu_si256((__m256i*)tmp[4], x4);
        _mm256_storeu_si256((__m256i*)tmp[5], x5);
        _mm256_storeu_si256((__m256i*)tmp[6], x6);
        _mm256_storeu_si256((__m256i*)tmp[7], x7);
        _mm256_storeu_si256((__m256i*)tmp[8], x8);
        _mm256_storeu_si256((__m256i*)tmp[9], x9);
        _mm256_storeu_si256((__m256i*)tmp[10], x10);
        _mm256_storeu_si256((__m256i*)tmp[11], x11);
        _mm256_storeu_si256((__m256i*)tmp[12], x12);
        _mm256_storeu_si256((__m256i*)tmp[13], x13);
        _mm256_storeu_si256((__m256i*)tmp[14], x14);
        _mm256_storeu_si256((__m256i*)tmp[15], x15);

        for (int b = 0; b < 8; b++) {
            unsigned char block[64];
            uint32_t *w = (uint32_t*)block;
            for (int j = 0; j < 16; j++) w[j] = tmp[j][b];
            const unsigned char *src = in ? in + off + b*64 : NULL;
            unsigned char *dst = out + off + b*64;
            if (src) {
                for (int j = 0; j < 64; j++) dst[j] = block[j] ^ src[j];
            } else {
                memcpy(dst, block, 64);
            }
        }
        counter += 8;
        off += 512;
    }
    /* tail via scalar */
    while (off < len) {
        uint32_t st[16] = {s0,s1,s2,s3,k[0],k[1],k[2],k[3],k[4],k[5],k[6],k[7],counter,n0,n1,n2};
        uint32_t w[16];
        memcpy(w, st, 64);
        for (int r = 0; r < 10; r++) {
            qr(&w[0],&w[4],&w[8],&w[12]);
            qr(&w[1],&w[5],&w[9],&w[13]);
            qr(&w[2],&w[6],&w[10],&w[14]);
            qr(&w[3],&w[7],&w[11],&w[15]);
            qr(&w[0],&w[5],&w[10],&w[15]);
            qr(&w[1],&w[6],&w[11],&w[12]);
            qr(&w[2],&w[7],&w[8],&w[13]);
            qr(&w[3],&w[4],&w[9],&w[14]);
        }
        for (int j = 0; j < 16; j++) w[j] += st[j];
        size_t n = len - off; if (n > 64) n = 64;
        unsigned char *dst = out + off;
        const unsigned char *src = in + off;
        unsigned char *ks = (unsigned char*)w;
        for (size_t j = 0; j < n; j++) dst[j] = ks[j] ^ src[j];
        counter++;
        off += n;
    }
}

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t N = 40*1024*1024;
    unsigned char *in = malloc(N);
    unsigned char *out1 = malloc(N);
    unsigned char *out2 = malloc(N);
    memset(in, 0x5a, N);
    unsigned char key[32];
    unsigned char nonce[12];
    for (int i = 0; i < 32; i++) key[i] = i+1;
    for (int i = 0; i < 12; i++) nonce[i] = i+3;
    uint32_t counter_block[4];
    counter_block[0] = 1;
    memcpy(counter_block+1, nonce, 12);
    uint32_t keyw[8];
    memcpy(keyw, key, 32);

    chacha20_xor(out1, in, N, key, nonce, 1);
    ChaCha20_ctr32(out2, in, N, keyw, counter_block);
    if (memcmp(out1, out2, N) != 0) {
        printf("MISMATCH\n");
        for (size_t i = 0; i < N; i++) if (out1[i]!=out2[i]) { printf("at %zu ours %02x ssl %02x\n", i, out1[i], out2[i]); break; }
    } else printf("match\n");

    int iters = 5;
    double t0 = now();
    for (int i = 0; i < iters; i++) chacha20_xor(out1, in, N, key, nonce, 1);
    double dt = (now()-t0)/iters;
    printf("avx2 %.2f ms  %.0f MB/s\n", dt*1000, N/dt/1e6);

    t0 = now();
    for (int i = 0; i < iters; i++) ChaCha20_ctr32(out2, in, N, keyw, counter_block);
    dt = (now()-t0)/iters;
    printf("ssl  %.2f ms  %.0f MB/s\n", dt*1000, N/dt/1e6);
    return 0;
}
