            const unsigned char *src = in + off + b*64;
            unsigned char *dst = out + off + b*64;
            for (int j = 0; j < 64; j++) dst[j] = block[j] ^ src[j];
        }
        counter += 8;
        off += 512;
    }
    while (off < len) {
        uint32_t st[16] = {s0,s1,s2,s3,k[0],k[1],k[2],k[3],k[4],k[5],k[6],k[7],counter,n0,n1,n2};
