        memcpy(w, st, 64);
        for (int r = 0; r < 10; r++) {
            qr(&w[0],&w[4],&w[8],&w[12]);
            qr(&w[1],&w[5],&w[9],&w[13]);
            qr(&w[2],&w[6],&w[10],&w[14]);
            qr(&w[3],&w[7],&w[11],&w[15]);
            qr(&w[0],&w[5],&w[10],&w[15]);
            qr(&w[1],&w[6],&w[11],&w[12]);
            qr(&w[2],&w[7],&w[8],&w[13]);
            qr(&w[3],&w[4],&w[9],&w[14]);
