        for (int j = 0; j < 16; j++) w[j] += st[j];
        size_t n = len - off; if (n > 64) n = 64;
        unsigned char *dst = out + off;
        const unsigned char *src = in + off;
        unsigned char *ks = (unsigned char*)w;
        for (size_t j = 0; j < n; j++) dst[j] = ks[j] ^ src[j];
        counter++;
        off += n;
