#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <immintrin.h>

int ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                   const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

static void parallel_chacha(unsigned char *out, const unsigned char *in, size_t len,
                            const unsigned int key[8], uint32_t counter0,
                            const unsigned char nonce[12], int nthreads) {
    if (len == 0) return;
    if (nthreads < 1) nthreads = 1;
    if ((size_t)nthreads * 64 > len) nthreads = (int)(len / 64);
    if (nthreads < 1) nthreads = 1;
    /* align chunks to 64 */
    size_t chunk = ((len / nthreads + 63) & ~(size_t)63);
    if (chunk == 0) chunk = len;
    pthread_t th[16];
    job_t jobs[16];
    int used = 0;
    for (int i = 0; i < nthreads && i < 16; i++) {
        size_t start = (size_t)i * chunk;
        if (start >= len) break;
        size_t length = chunk;
        if (start + length > len) length = len - start;
        jobs[i].out = out + start;
        jobs[i].in = in + start;
        jobs[i].len = length;
        memcpy(jobs[i].key, key, 32);
        uint32_t block = counter0 + (uint32_t)(start / 64);
        jobs[i].counter[0] = block;
        memcpy(jobs[i].counter + 1, nonce, 12);
        if (i == 0 && nthreads == 1) { worker(&jobs[i]); used = 0; break; }
        pthread_create(&th[i], NULL, worker, &jobs[i]);
        used++;
    }
    for (int i = 0; i < used; i++) pthread_join(th[i], NULL);
}

static void aead_encrypt(unsigned char *ct, unsigned char tag[16],
                         const unsigned char key[32], const unsigned char nonce[12],
                         const unsigned char *pt, size_t pt_len,
                         const unsigned char *aad, size_t aad_len,
                         int nthreads) {
    unsigned int keyw[8];
    memcpy(keyw, key, 32);
    unsigned int ctr0[4];
    ctr0[0] = 0;
    memcpy(ctr0+1, nonce, 12);
    unsigned char block0[64] = {0};
    unsigned char otk[64];
    ChaCha20_ctr32(otk, block0, 64, keyw, ctr0);

    parallel_chacha(ct, pt, pt_len, keyw, 1, nonce, nthreads);

    size_t ctxsz = Poly1305_ctx_size();
    unsigned char ctx[512];
    if (ctxsz > sizeof ctx) abort();
    Poly1305_Init(ctx, otk);
    if (aad_len) {
        Poly1305_Update(ctx, aad, aad_len);
        size_t p = (16 - (aad_len & 15)) & 15;
        if (p) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, p);
        }
    }
    if (pt_len) {
        Poly1305_Update(ctx, ct, pt_len);
        size_t p = (16 - (pt_len & 15)) & 15;
        if (p) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, p);
        }
    }
    unsigned char lens[16];
    uint64_t al = aad_len, pl = pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens+8, &pl, 8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
