/* reference via EVP for check */
#include <openssl/evp.h>
static int evp_encrypt(unsigned char *out, unsigned char tag[16],
                       const unsigned char key[32], const unsigned char nonce[12],
                       const unsigned char *pt, size_t pt_len,
                       const unsigned char *aad, size_t aad_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len=0, outlen=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    if (aad_len) EVP_EncryptUpdate(ctx, NULL, &len, aad, (int)aad_len);
    EVP_EncryptUpdate(ctx, out, &len, pt, (int)pt_len);
    outlen = len;
    EVP_EncryptFinal_ex(ctx, out+outlen, &len);
    outlen += len;
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return outlen;
}

