#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

int ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                   const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define MAXW 8

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
    int has_job;
    int stop;
    pthread_mutex_t mu;
    pthread_cond_t cv_job;
    pthread_cond_t cv_done;
    pthread_t th;
} worker_t;

static worker_t workers[MAXW];
static int pool_ready = 0;
static int pool_n = 0;
static pthread_mutex_t pool_mu = PTHREAD_MUTEX_INITIALIZER;

static void *worker_main(void *arg) {
    worker_t *w = (worker_t *)arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->has_job && !w->stop) pthread_cond_wait(&w->cv_job, &w->mu);
        if (w->stop) { pthread_mutex_unlock(&w->mu); break; }
        unsigned char *out = w->out;
        const unsigned char *in = w->in;
        size_t len = w->len;
        unsigned int key[8];
        unsigned int counter[4];
        memcpy(key, w->key, 32);
        memcpy(counter, w->counter, 16);
        pthread_mutex_unlock(&w->mu);

        ChaCha20_ctr32(out, in, len, key, counter);

        pthread_mutex_lock(&w->mu);
        w->has_job = 0;
        pthread_cond_signal(&w->cv_done);
    }
    return NULL;
}

static void ensure_pool(int n) {
    if (pool_ready) return;
    pthread_mutex_lock(&pool_mu);
    if (!pool_ready) {
        if (n < 1) n = 1;
        if (n > MAXW) n = MAXW;
        pool_n = n;
        for (int i = 0; i < n; i++) {
            memset(&workers[i], 0, sizeof(workers[i]));
            pthread_mutex_init(&workers[i].mu, NULL);
            pthread_cond_init(&workers[i].cv_job, NULL);
            pthread_cond_init(&workers[i].cv_done, NULL);
            pthread_create(&workers[i].th, NULL, worker_main, &workers[i]);
        }
        pool_ready = 1;
    }
    pthread_mutex_unlock(&pool_mu);
}

static void parallel_chacha(unsigned char *out, const unsigned char *in, size_t len,
                            const unsigned int key[8], uint32_t counter0,
                            const unsigned char nonce[12], int nthreads) {
    if (len == 0) return;
    if (nthreads < 1) nthreads = 1;
    if (len < 512 * 1024) nthreads = 1;
    if ((size_t)nthreads * 64 > len) {
        nthreads = (int)(len / 64);
        if (nthreads < 1) nthreads = 1;
    }
    if (nthreads > MAXW) nthreads = MAXW;
    ensure_pool(nthreads);
    if (nthreads > pool_n) nthreads = pool_n;

    if (nthreads == 1) {
        unsigned int counter[4];
        counter[0] = counter0;
        memcpy(counter + 1, nonce, 12);
        ChaCha20_ctr32(out, in, len, key, counter);
        return;
    }

    size_t chunk = len / (size_t)nthreads;
    chunk = (chunk + 63) & ~(size_t)63;
    if (chunk == 0) chunk = len;

    int used = 0;
    for (int i = 0; i < nthreads; i++) {
        size_t start = (size_t)i * chunk;
        if (start >= len) break;
        size_t length = (i == nthreads - 1 || start + chunk > len) ? (len - start) : chunk;
        worker_t *w = &workers[used];
        pthread_mutex_lock(&w->mu);
        w->out = out + start;
        w->in = in + start;
        w->len = length;
        memcpy(w->key, key, 32);
        uint32_t block = counter0 + (uint32_t)(start / 64);
        w->counter[0] = block;
        memcpy(w->counter + 1, nonce, 12);
        w->has_job = 1;
        pthread_cond_signal(&w->cv_job);
        pthread_mutex_unlock(&w->mu);
        used++;
    }
    for (int i = 0; i < used; i++) {
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        while (w->has_job) pthread_cond_wait(&w->cv_done, &w->mu);
        pthread_mutex_unlock(&w->mu);
    }
}

