    unsigned int keyw[8];
    memcpy(keyw, key, 32);
    unsigned int ctr0[4];
    ctr0[0] = 0;
    memcpy(ctr0 + 1, nonce, 12);
    unsigned char block0[64];
    memset(block0, 0, 64);
    unsigned char otk[64];
    ChaCha20_ctr32(otk, block0, 64, keyw, ctr0);

    parallel_chacha(ct, pt, pt_len, keyw, 1, nonce, nthreads);

    unsigned char ctx[512];
    Poly1305_Init(ctx, otk);
    if (aad && aad_len) {
        Poly1305_Update(ctx, aad, aad_len);
        size_t p = (16 - (aad_len & 15)) & 15;
        if (p) { unsigned char z[16] = {0}; Poly1305_Update(ctx, z, p); }
    }
    if (pt_len) {
        Poly1305_Update(ctx, ct, pt_len);
        size_t p = (16 - (pt_len & 15)) & 15;
        if (p) { unsigned char z[16] = {0}; Poly1305_Update(ctx, z, p); }
    }
    unsigned char lens[16];
    uint64_t al = (aad && aad_len) ? (uint64_t)aad_len : 0;
    uint64_t pl = (uint64_t)pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &pl, 8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
    return 0;
}
