{"command":"# persistent pool + poly1305 on main after, measure in C without python
# also try parallel poly1305 by splitting blocks and combining? Poly1305 isn't linear easily
# (h + m) * r, can do parallel independent powers if we precompute r^k. Complex.
# Focus: persistent pool C benchmark of full AEAD including nothing else.

cat > .build/poolbench.c << 'EOF'
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdatomic.h>

int ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                   const unsigned int key[8], const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define MAXW 8
typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
    atomic_int ready; /* 0 idle, 1 job, 2 done */
    int stop;
    pthread_t th;
} worker_t;

static worker_t W[MAXW];
static int NW = 0;

static void *loop(void *arg) {
    worker_t *w = arg;
    for (;;) {
        while (atomic_load_explicit(&w->ready, memory_order_acquire) != 1) {
            if (w->stop) return NULL;
            /* spin briefly */
        }
        ChaCha20_ctr32(w->out, w->in, w->len, w->key, w->counter);
        atomic_store_explicit(&w->ready, 2, memory_order_release);
    }
}

static void init_pool(int n) {
    NW = n;
    for (int i = 0; i < n; i++) {
        atomic_store(&W[i].ready, 0);
        W[i].stop = 0;
        pthread_create(&W[i].th, NULL, loop, &W[i]);
    }
}

static void parallel(unsigned char *out, const unsigned char *in, size_t len,
                     const unsigned int key[8], const unsigned char nonce[12], int nt) {
    if (nt < 1) nt = 1;
    if (nt > NW) nt = NW;
    if (len < 256*1024) nt = 1;
    size_t chunk = (len / nt + 63) & ~(size_t)63;
    if (chunk == 0) { nt = 1; chunk = len; }
    int used = 0;
    for (int i = 0; i < nt; i++) {
        size_t start = (size_t)i * chunk;
        if (start >= len) break;
        size_t length = (i == nt-1 || start+chunk > len) ? len-start : chunk;
        worker_t *w = &W[i];
        w->out = out+start; w->in = in+start; w->len = length;
        memcpy(w->key, key, 32);
        w->counter[0] = 1 + (unsigned)(start/64);
        memcpy(w->counter+1, nonce, 12);
        if (nt == 1) { ChaCha20_ctr32(w->out, w->in, w->len, w->key, w->counter); return; }
        atomic_store_explicit(&w->ready, 1, memory_order_release);
        used++;
    }
    for (int i = 0; i < used; i++) {
        while (atomic_load_explicit(&W[i].ready, memory_order_acquire) != 2) ;
        atomic_store_explicit(&W[i].ready, 0, memory_order_relaxed);
    }
}

static void aead(unsigned char *ct, unsigned char tag[16],
                 const unsigned char key[32], const unsigned char nonce[12],
                 const unsigned char *pt, size_t n,
                 const unsigned char *aad, size_t aad_len, int nt) {
    unsigned int keyw[8]; memcpy(keyw, key, 32);
    unsigned int ctr0[4]; ctr0[0]=0; memcpy(ctr0+1, nonce, 12);
    unsigned char zeros[64]={0}, otk[64];
    ChaCha20_ctr32(otk, zeros, 64, keyw, ctr0);
    parallel(ct, pt, n, keyw, nonce, nt);
    unsigned char ctx[512];
    Poly1305_Init(ctx, otk);
    if (aad_len) {
        Poly1305_Update(ctx, aad, aad_len);
        size_t p=(16-(aad_len&15))&15; if (p) Poly1305_Update(ctx, zeros, p);
    }
    if (n) {
        Poly1305_Update(ctx, ct, n);
        size_t p=(16-(n&15))&15; if (p) Poly1305_Update(ctx, zeros, p);
    }
    unsigned char lens[16];
    uint64_t al=aad_len, pl=n;
    memcpy(lens,&al,8); memcpy(lens+8,&pl,8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

int main() {
    init_pool(6);
    size_t N=40ull*1024*1024;
    unsigned char *pt=malloc(N), *ct=malloc(N);
    memset(pt,1,N);
    unsigned char key[32], nonce[12], aad[32], tag[16];
    memset(key,9,32); memset(nonce,4,12); memset(aad,5,32);
    for (int nt=1; nt<=6; nt++) {
        aead(ct, tag, key, nonce, pt, N, aad, 32, nt);
        double t0=now(); int iters=4;
        for(int i=0;i<iters;i++) aead(ct, tag, key, nonce, pt, N, aad, 32, nt);
        double dt=(now()-t0)/iters;
        printf("nt=%d %.2f ms %.0f MB/s\n", nt, dt*1000, N/dt/1e6);
    }
    return 0;
}
EOF
